    image_patch = ImagePatch(image)
    bench_patches = image_patch.find("bench")
    park_patches = image_patch.find("park")

    if not bench_patches or not park_patches:
        return image_patch

    bench_depths = [patch.compute_depth() for patch in bench_patches]
    park_depths = [patch.compute_depth() for patch in park_patches]

    max_bench_depth = max(bench_depths)
    min_park_depth = min(park_depths)

    if max_bench_depth < min_park_depth:
        return image_patch

    bench_patches_in_park = [patch for patch in bench_patches if patch.compute_depth() < min_park_depth]

    if bench_patches_in_park:
        return max(bench_patches_in_park, key=lambda p: p.compute_depth())

    return image_patch

